<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-alt: #f8fafc;
      --text: #0f172a;
      --muted: #475569;
      --border: #d7dee9;
      --primary: #2563eb;
      --primary-strong: #1d4ed8;
      --primary-soft: #dbeafe;
      --focus: #0f62fe;
      --shadow: 0 20px 60px rgba(15, 23, 42, 0.12);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, #eaf2ff 0%, transparent 35%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
    }

    .skip-link {
      position: absolute;
      top: 0;
      left: 0;
      transform: translateY(-120%);
      padding: 0.75rem 1rem;
      background: var(--surface);
      color: var(--text);
      border: 2px solid var(--focus);
      border-radius: 0 0 12px 0;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem 1rem;
    }

    .card {
      width: min(100%, 640px);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: clamp(1.5rem, 4vw, 2.5rem);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--primary-strong);
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(1.75rem, 3vw, 2.5rem);
      line-height: 1.15;
    }

    .intro {
      margin: 0 0 1.75rem;
      color: var(--muted);
      max-width: 60ch;
    }

    .form-field {
      margin: 0;
      padding: 1.25rem;
      border: 1px solid var(--border);
      border-radius: 18px;
      background: var(--surface-alt);
    }

    fieldset {
      border: 0;
      padding: 0;
      margin: 0;
      min-width: 0;
    }

    legend {
      padding: 0;
      margin: 0 0 0.5rem;
      font-size: 1.125rem;
      font-weight: 700;
    }

    .hint {
      margin: 0 0 1rem;
      color: var(--muted);
    }

    .options {
      display: grid;
      gap: 0.75rem;
    }

    .option {
      display: flex;
      align-items: center;
      gap: 0.875rem;
      padding: 0.95rem 1rem;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 14px;
      cursor: pointer;
      transition: border-color 150ms ease, box-shadow 150ms ease, transform 150ms ease;
    }

    .option:hover {
      border-color: #b9c5d6;
      transform: translateY(-1px);
    }

    .option input {
      width: 1.1rem;
      height: 1.1rem;
      margin: 0;
      accent-color: var(--primary);
      flex: 0 0 auto;
    }

    .option span {
      font-weight: 600;
    }

    .option:has(input:focus-visible) {
      border-color: var(--focus);
      box-shadow: 0 0 0 4px var(--primary-soft);
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      margin-top: 1.25rem;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.35rem;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
    }

    .submit {
      background: linear-gradient(180deg, var(--primary) 0%, var(--primary-strong) 100%);
      color: #fff;
      box-shadow: 0 14px 30px rgba(37, 99, 235, 0.25);
    }

    .submit:hover {
      filter: brightness(1.02);
    }

    .submit:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5em;
      margin: 1rem 0 0;
      color: var(--muted);
    }

    .status[data-state="error"] {
      color: #b91c1c;
    }

    @media (max-width: 480px) {
      .card {
        padding: 1.25rem;
      }

      .form-field {
        padding: 1rem;
      }

      .option {
        align-items: flex-start;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-alt: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --border: ButtonBorder;
        --primary: ButtonText;
        --primary-strong: ButtonText;
        --primary-soft: ButtonBorder;
        --focus: Highlight;
      }

      .card,
      .form-field,
      .option,
      .submit {
        forced-color-adjust: auto;
      }

      .submit {
        border: 1px solid ButtonBorder;
        color: ButtonText;
        background: ButtonFace;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Settings</p>
      <h1 id="page-title">Notification preferences</h1>
      <p class="intro">Choose the single channel you want us to use when we contact you.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="notification-help notification-status">
            <legend>How do you prefer to receive notifications?</legend>
            <p class="hint" id="notification-help">Select one option below.</p>

            <div class="options">
              <label class="option" for="email">
                <input type="radio" id="email" name="notification-method" value="Email" required />
                <span>Email</span>
              </label>

              <label class="option" for="sms">
                <input type="radio" id="sms" name="notification-method" value="SMS" />
                <span>SMS</span>
              </label>

              <label class="option" for="push">
                <input type="radio" id="push" name="notification-method" value="Push Notifications" />
                <span>Push Notifications</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button class="submit" type="submit">Submit</button>
        </div>

        <p id="notification-status" class="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("notification-form");
    const status = document.getElementById("notification-status");
    const options = Array.from(form.elements["notification-method"]);

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selected = form.elements["notification-method"].value;

      if (!selected) {
        status.textContent = "Please choose Email, SMS, or Push Notifications before submitting.";
        status.dataset.state = "error";
        options[0].focus();
        return;
      }

      status.dataset.state = "success";
      status.textContent = `Saved preference: ${selected}.`;
    });
  </script>
</body>
</html>
