<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Settings</p>
      <h1 id="page-title">Notification preferences</h1>
      <p class="intro">Choose the single channel you want us to use when we contact you.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="notification-help notification-status">
            <legend>How do you prefer to receive notifications?</legend>
            <p class="hint" id="notification-help">Select one option below.</p>

            <div class="options">
              <label class="option" for="email">
                <input type="radio" id="email" name="notification-method" value="Email" required />
                <span>Email</span>
              </label>

              <label class="option" for="sms">
                <input type="radio" id="sms" name="notification-method" value="SMS" />
                <span>SMS</span>
              </label>

              <label class="option" for="push">
                <input type="radio" id="push" name="notification-method" value="Push Notifications" />
                <span>Push Notifications</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button class="submit" type="submit">Submit</button>
        </div>

        <p id="notification-status" class="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("notification-form");
    const status = document.getElementById("notification-status");
    const options = Array.from(form.querySelectorAll('input[name="notification-method"]'));

    const setInvalidState = (isInvalid) => {
      options.forEach((option) => {
        option.setAttribute("aria-invalid", String(isInvalid));
      });
    };

    options.forEach((option) => {
      option.addEventListener("change", () => {
        setInvalidState(false);
        status.removeAttribute("data-state");
        status.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selected = form.elements["notification-method"].value;

      if (!selected) {
        setInvalidState(true);
        status.textContent = "Please choose Email, SMS, or Push Notifications before submitting.";
        status.dataset.state = "error";
        options[0].focus();
        return;
      }

      setInvalidState(false);
      status.dataset.state = "success";
      status.textContent = `Saved preference: ${selected}.`;
    });
  </script>
</body>
</html>
